using System.ComponentModel;
using ModelContextProtocol.Server;

namespace ConfigMcpServer.Tools;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Get the value of a configuration key.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up")] string key)
    {
        var config = AppConfig.Current;
        return config.TryGetValue(key, out var value)
            ? value
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfig.Current.Keys.Order());
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ConfigMcpServer.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig.Current, AppConfig.JsonOptions);
    }

    [McpServerResource(
        UriTemplate = "config://app/{section}",
        Name = "Config Section",
        MimeType = "application/json"),
     Description("Returns configuration values for a specific section.")]
    public static string GetConfigSection(
        [Description("Section name: database, features, or api")] string section)
    {
        var all = AppConfig.Current;
        var prefix = $"{section}:";
        var sectionData = all
            .Where(kv => kv.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key[prefix.Length..], kv => kv.Value);

        return sectionData.Count > 0
            ? JsonSerializer.Serialize(sectionData, AppConfig.JsonOptions)
            : JsonSerializer.Serialize(new { error = $"Section '{section}' not found" });
    }
}

using System.Text.Json;

namespace ConfigMcpServer;

/// <summary>
/// Sample configuration data exposed via MCP resources and tools.
/// </summary>
public static class AppConfig
{
    public static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    public static Dictionary<string, string> Current { get; } = new()
    {
        ["database:host"] = "localhost",
        ["database:port"] = "5432",
        ["database:name"] = "appdb",
        ["features:dark-mode"] = "true",
        ["features:beta-access"] = "false",
        ["api:timeout-seconds"] = "30",
        ["api:max-retries"] = "3",
    };
}

