using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace ConfigMcpServer.Resources;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAppConfig()
    {
        return JsonSerializer.Serialize(AppConfig.Current, AppConfig.JsonOptions);
    }

    [McpServerResource(
        UriTemplate = "config://app/{section}",
        Name = "Config Section",
        MimeType = "application/json"),
     Description("Returns configuration values for a specific section.")]
    public static string GetConfigSection(
        [Description("Section name: database, features, or api")] string section)
    {
        var all = AppConfig.Current;
        var prefix = $"{section}:";
        var sectionData = all
            .Where(kv => kv.Key.StartsWith(prefix, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key[prefix.Length..], kv => kv.Value);

        return sectionData.Count > 0
            ? JsonSerializer.Serialize(sectionData, AppConfig.JsonOptions)
            : JsonSerializer.Serialize(new { error = $"Section '{section}' not found" });
    }
}

